// ── 8. Real-Time Lock-Free SOFA-SAF-RIR Coupling Evaluators ──
inline void computeSofaRirCoupling(const float q[7], float& outEarlyBoost, float& outLateDecorrel, float& outRt60Delta, float& outWetScale) noexcept {
    float qn[7]{};
    for (int i = 0; i < 7; ++i) {
        const float s3 = 3.0f * kMasterSafSigma[i];
        // Handle both raw q (in +-3*sigma) and pre-normalized q (in [-1, 1])
        const float v = q ? q[i] : kMasterSafGoldenQ[i];
        qn[i] = (std::fabs(v) <= 0.20f && s3 > 1e-6f) ? std::clamp(v / s3, -1.0f, 1.0f) : std::clamp(v, -1.0f, 1.0f);
    }
    float mod[4]{};
    for (int r = 0; r < 4; ++r) {
        float acc = 0.0f;
        for (int k = 0; k < 7; ++k) acc += kSofaToRirCoupling[r][k] * qn[k];
        mod[r] = acc;
    }
    outEarlyBoost   = std::clamp(1.0f + mod[0], 0.80f, 1.35f);
    outLateDecorrel = std::clamp(0.62f + mod[1], 0.25f, 0.95f);
    outRt60Delta    = std::clamp(mod[2], -0.15f, 0.15f);
    outWetScale     = std::clamp(1.0f + mod[3], 0.75f, 1.25f);
}

